<?php defined( 'ABSPATH' ) || exit; ?>
<header class="dxbus-view__head"><p class="dxbus-eyebrow">The journey is the story</p><h2>Route stories</h2><p>Places, photographs and moments along the way.</p></header><div class="dxbus-story-grid"><?php foreach ( $context['journeys'] as $index => $journey ) : ?><article class="dxbus-card dxbus-story-card<?php echo 0 === $index ? ' is-featured' : ''; ?>"><a href="<?php echo esc_url( $journey['url'] ); ?>"><?php if ( $journey['image_id'] ) : ?><?php echo wp_get_attachment_image( $journey['image_id'], 'large', false, array( 'loading' => 'lazy', 'decoding' => 'async' ) ); ?><?php endif; ?><div class="dxbus-card__body"><p class="dxbus-eyebrow"><?php echo esc_html( $journey['route'] ); ?> · Journey notes</p><h3><?php echo esc_html( $journey['title'] ); ?></h3><p><?php echo esc_html( $journey['start'] . ' → ' . $journey['end'] ); ?></p><time><?php echo esc_html( $journey['date'] ); ?></time><p><?php echo esc_html( wp_trim_words( $journey['excerpt'], 32 ) ); ?></p><span class="dxbus-link">Read the story ↗</span></div></a></article><?php endforeach; ?></div><?php if ( ! $context['journeys'] ) : ?><div class="dxbus-empty"><h3>This route’s story is still to come.</h3><p>No diary entries are associated with this route yet.</p><a href="<?php echo esc_url( home_url( '/buses/#bus-diary' ) ); ?>">Explore the wider diary ↗</a></div><?php endif; ?>
